=INSERT INTO estimates (estimate_id, lead_id, painter_id, estimate_version, estimate_json, estimate_mode, estimate_type, material_total, labour_cost, discount, grand_total, submitted_at)
VALUES (gen_random_uuid(), '{{$node["Webhook - POST Submit Estimate"].json["body"]["lead_id"]}}', '{{$node["Webhook - POST Submit Estimate"].json["body"]["painter_id"]}}', {{$node["Postgres - Calculate New Version"].json["new_version"]}}, '{{JSON.stringify($node["Webhook - POST Submit Estimate"].json["body"]["estimate_items"])}}'::jsonb, '{{$node["Webhook - POST Submit Estimate"].json["body"]["mode"]}}', '{{$node["Webhook - POST Submit Estimate"].json["body"]["estimate_type"]}}', {{$node["Webhook - POST Submit Estimate"].json["body"]["material_total"]}}, {{$node["Webhook - POST Submit Estimate"].json["body"]["labour_cost"]}}, {{$node["Webhook - POST Submit Estimate"].json["body"]["discount"] || 0}}, {{$node["Webhook - POST Submit Estimate"].json["body"]["grand_total"]}}, NOW())
RETURNING estimate_id;

parameters.jsCode:
const items = $node["Webhook - POST Submit Estimate"].json["body"]["estimate_items"] || [];
const estimateId = $node["Postgres - Insert Estimate"].json["estimate_id"];

if (items.length === 0) {
  return { query: "SELECT 1;" };
}

let query = "INSERT INTO estimate_items (estimate_item_id, estimate_id, product_id, quantity, rate, line_total) VALUES ";
const values = items.map(item => {
  const qty = parseFloat(item.quantity) || 0;
  const rate = parseFloat(item.rate) || 0;
  const total = qty * rate;
  return `(gen_random_uuid(), '${estimateId}', '${item.product_id}', ${qty}, ${rate}, ${total})`;
});
query += values.join(", ") + " RETURNING estimate_item_id;";

return { query: query };

